/** Tokens are 43 base64url characters (32 bytes), generated by the database. */
export const TOKEN_PATTERN = /^[A-Za-z0-9_-]{43}$/;

/** Reads the token from a URL fragment like "#AbC…". Returns null if it isn't a well-formed token. */
export function tokenFromHash(hash: string): string | null {
  const t = hash.replace(/^#/, "").trim();
  return TOKEN_PATTERN.test(t) ? t : null;
}

/**
 * The token lives in the fragment, which browsers never send to servers —
 * so it can't appear in hosting logs, analytics or Referer headers.
 */
export function portalUrl(origin: string, token: string): string {
  return `${origin.replace(/\/+$/, "")}/p#${token}`;
}

export const LINK_VALIDITY_DAYS = [7, 30, 90] as const;
